from pathlib import Path
import csv, json, math, random
from datetime import date, timedelta
root = Path(r'C:\Users\27793\Documents\project1\AI_Finance_Prototype')
for d in ['data','docs','scripts']:
    (root/d).mkdir(parents=True, exist_ok=True)
random.seed(20260714)
rows=[]; start=date(2026,1,15)
for i in range(180):
    close=100+0.035*i+4.2*math.sin(i/12)+1.8*math.sin(i/4.7)+random.gauss(0,0.9)
    open_p=close+random.gauss(0,0.6); high=max(open_p,close)+abs(random.gauss(0.8,0.35)); low=min(open_p,close)-abs(random.gauss(0.8,0.35))
    rows.append({'date':(start+timedelta(days=i)).isoformat(),'open':round(open_p,2),'high':round(high,2),'low':round(low,2),'close':round(close,2),'volume':int(900000+140000*math.sin(i/9)+random.randint(-80000,120000))})
for i,r in enumerate(rows):
    closes=[x['close'] for x in rows[max(0,i-4):i+1]]
    r['ma5']=round(sum(closes)/len(closes),2); r['volatility']=round(max(closes)-min(closes),2)
    r['frets_pred']=round(r['close']+0.65*math.sin((i+3)/10.5)+random.gauss(0,0.45),2)
    r['timegnn_pred']=round(r['close']+0.45*math.sin((i+1)/8)+random.gauss(0,0.55),2)
    r['ensemble_pred']=round((r['frets_pred']+r['timegnn_pred'])/2,2)
    err=abs(r['ensemble_pred']-r['close'])
    r['risk_level']='高' if err>1.15 or r['volatility']>5.2 else ('中' if err>0.65 or r['volatility']>3.8 else '低')
with open(root/'data'/'sample_finance_series.csv','w',newline='',encoding='utf-8-sig') as f:
    w=csv.DictWriter(f,fieldnames=list(rows[0].keys())); w.writeheader(); w.writerows(rows)
(root/'data'/'prototype_summary.json').write_text(json.dumps({'project':'AI金融时序预测与风险解释原型系统','data_rows':len(rows),'disclaimer':'仅用于社会实践展示、技术学习和风险识别科普，不构成投资建议。'},ensure_ascii=False,indent=2),encoding='utf-8')
html = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI金融时序预测与风险解释原型系统</title><style>
body{margin:0;font-family:"Microsoft YaHei",Arial,sans-serif;background:#f6f8fb;color:#172033}header{background:#10233f;color:white;padding:24px 34px}h1{margin:0 0 8px;font-size:27px}header p{margin:0;color:#d8e1f1}.wrap{max-width:1180px;margin:0 auto;padding:24px}.grid{display:grid;gap:16px}.cards{grid-template-columns:repeat(4,1fr)}.two{grid-template-columns:1.3fr .7fr}section,.card{background:#fff;border:1px solid #d9dee8;border-radius:8px;padding:16px}h2{margin:0 0 12px;color:#1f4d78;font-size:18px}.label{color:#5b6475;font-size:13px}.value{font-size:25px;font-weight:700;margin-top:6px}.badge{display:inline-block;padding:4px 9px;border-radius:999px;border:1px solid #d9dee8;font-size:12px}.risk-high{color:#b42318;background:#fff5f4;border-color:#f1b5b1}.risk-mid{color:#8a6100;background:#fff9e8;border-color:#ead394}.risk-low{color:#0f7a5a;background:#f0fbf7;border-color:#b5dfd0}canvas{width:100%;height:320px;border:1px solid #eef1f6;border-radius:6px;background:white}.flow{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.node{padding:10px 12px;border:1px solid #cfd8e6;background:#f9fbfe;border-radius:6px;font-size:13px}.note{color:#5b6475;line-height:1.75;font-size:13px}.explain{border-left:4px solid #2457a6;background:#f7faff;padding:12px;line-height:1.8}button{border:1px solid #c7d2e3;background:white;border-radius:6px;padding:8px 10px;margin:0 6px 10px 0;cursor:pointer}button.active{background:#2457a6;color:white}table{width:100%;border-collapse:collapse;font-size:13px}th,td{border-bottom:1px solid #e8edf4;padding:8px;text-align:left;vertical-align:top}th{background:#f3f6fa}@media(max-width:900px){.cards,.two{grid-template-columns:1fr}.wrap{padding:14px}}
</style></head><body><header><h1>AI金融时序预测与风险解释原型系统</h1><p>基于 FreTS、Time-GNN 与 SEP 思想的社会实践展示原型；仅用于技术学习、风险识别科普和项目汇报，不构成投资建议。</p></header><div class="wrap">
<div class="grid cards"><div class="card"><div class="label">样例时间序列</div><div class="value" id="mRows">180</div></div><div class="card"><div class="label">当前风险等级</div><div class="value"><span id="mRisk" class="badge">中</span></div></div><div class="card"><div class="label">模型平均误差</div><div class="value" id="mMae">-</div></div><div class="card"><div class="label">项目可交付</div><div class="value">4 模块</div></div></div>
<section style="margin-top:16px"><h2>一、项目流程</h2><div class="flow"><div class="node">公开金融时序数据</div>→<div class="node">清洗与技术指标</div>→<div class="node">FreTS 频域预测</div>+<div class="node">Time-GNN 图时序建模</div>→<div class="node">趋势可视化</div>→<div class="node">LLM 风险解释</div></div></section>
<div class="grid two" style="margin-top:16px"><section><h2>二、预测结果可视化</h2><button class="active" data-mode="price">真实值 vs 预测值</button><button data-mode="error">预测误差</button><button data-mode="risk">风险等级</button><canvas id="chart" width="900" height="360"></canvas><p class="note">蓝线为真实收盘价，绿线为 FreTS 频域预测，橙线为 Time-GNN 动态图预测。样例数据用于演示流程，真实研究时替换为公开股票或指数数据。</p></section><section><h2>三、模型解释</h2><div id="explainBox" class="explain"></div><p class="note">本项目不强调“精准预测股价”，而是展示 AI 如何处理金融时序数据、识别波动风险，并把模型输出转化为普通学生能理解的风险提示。</p></section></div>
<section style="margin-top:16px"><h2>四、模块说明</h2><table><tr><th>模块</th><th>实现内容</th><th>对应论文/源码</th><th>当前可展示成果</th></tr><tr><td>数据整理</td><td>收盘价、成交量、均线、波动率、风险标签</td><td>特征选择综述、股票预测综述</td><td>CSV 数据表、数据来源说明</td></tr><tr><td>频域预测</td><td>从时间序列频率变化中学习趋势与周期特征</td><td>FreTS</td><td>已部署跑通，可截图训练日志</td></tr><tr><td>图时序建模</td><td>将多指标或多股票关联视为动态图结构</td><td>Time-GNN、Graph Time-series Survey</td><td>已部署跑通，可截图输出目录与指标</td></tr><tr><td>解释与科普</td><td>把预测趋势、误差和风险因素转化为自然语言解释</td><td>SEP</td><td>解释模板、风险提示文案、科普讲稿</td></tr></table></section>
</div><script>const data=__DATA__;const canvas=document.getElementById('chart'),ctx=canvas.getContext('2d');function mae(){return data.reduce((s,d)=>s+Math.abs(d.ensemble_pred-d.close),0)/data.length}function riskClass(r){return r==='高'?'risk-high':r==='中'?'risk-mid':'risk-low'}function scale(vals){const min=Math.min(...vals),max=Math.max(...vals);return v=>320-(v-min)/(max-min||1)*280}let currentScale=v=>v,legendX=0;function axes(){ctx.strokeStyle='#d9dee8';ctx.beginPath();ctx.moveTo(50,20);ctx.lineTo(50,320);ctx.lineTo(870,320);ctx.stroke()}function line(vals,color,label){const sx=i=>50+i*820/(vals.length-1);ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();vals.forEach((v,i)=>{const x=sx(i),y=currentScale(v);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle=color;ctx.fillRect(62+legendX,22,12,12);ctx.fillStyle='#28384f';ctx.fillText(label,80+legendX,32);legendX+=145}function render(mode='price'){ctx.clearRect(0,0,900,360);ctx.font='12px Microsoft YaHei, Arial';axes();legendX=0;if(mode==='price'){const c=data.map(d=>d.close),f=data.map(d=>d.frets_pred),t=data.map(d=>d.timegnn_pred);currentScale=scale([...c,...f,...t]);line(c,'#2457a6','真实值');line(f,'#0f7a5a','FreTS');line(t,'#b26a00','Time-GNN')}else if(mode==='error'){const e=data.map(d=>Math.abs(d.ensemble_pred-d.close));currentScale=scale(e);line(e,'#b42318','集成误差')}else{const s=data.map(d=>d.risk_level==='高'?3:d.risk_level==='中'?2:1);currentScale=scale(s);line(s,'#7a5a00','风险等级 1-3')}ctx.fillStyle='#5b6475';ctx.fillText(data[0].date,50,342);ctx.fillText(data[data.length-1].date,790,342)}function explain(){const d=data[data.length-1],c=riskClass(d.risk_level);document.getElementById('mRows').textContent=data.length;document.getElementById('mMae').textContent=mae().toFixed(3);const b=document.getElementById('mRisk');b.textContent=d.risk_level;b.className='badge '+c;document.getElementById('explainBox').innerHTML=`最近一期样例数据显示，真实收盘价为 <b>${d.close}</b>，FreTS 预测为 <b>${d.frets_pred}</b>，Time-GNN 预测为 <b>${d.timegnn_pred}</b>，集成预测为 <b>${d.ensemble_pred}</b>。当前风险等级判定为 <span class="badge ${c}">${d.risk_level}</span>。该判断主要来自预测误差、近期波动率和趋势变化。结果只用于技术展示和风险识别科普，不能作为投资建议。`}document.querySelectorAll('button').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');render(btn.dataset.mode)});explain();render();</script></body></html>'''
